#maintenanceCard[hidden],#insight-tab-maintenance[hidden]{display:none}.service-notice{font-weight:750;margin:12px 0;line-height:1.5}.service-notice.attention,.maintenance-callout.attention{border-left:4px solid var(--acc);padding:12px;background:var(--soft);border-radius:6px}.maintenance-callout{margin:0 0 18px;line-height:1.6}.maintenance-toggle{display:flex;align-items:center;gap:10px}.maintenance-toggle input{width:20px;height:20px}.insight-shell{padding:0;overflow:hidden}.insight-head{padding:24px 24px 18px;display:flex;justify-content:space-between;gap:16px;align-items:start}.insight-head h2{font-size:22px;letter-spacing:-.03em;margin:0}.insight-head .sub{max-width:560px}.insight-badge{font-size:12px;background:var(--soft);padding:7px 10px;border-radius:20px;white-space:nowrap}.insight-nav{display:flex;gap:4px;border-bottom:1px solid var(--line);padding:0 18px;overflow:auto}.insight-nav button{border-radius:0;background:transparent;color:var(--mut);margin:0;padding:14px 12px;border-bottom:3px solid transparent;white-space:nowrap}.insight-nav button[aria-selected=true]{color:var(--acc);border-color:var(--acc);font-weight:750}.insight-panel{padding:24px}.insight-panel[hidden]{display:none}.metric-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.metric{display:block;position:relative;text-align:left;background:var(--soft);color:var(--ink);border:1px solid transparent;margin:0;padding:18px;border-radius:12px;min-width:0}.metric:hover,.metric[aria-pressed=true]{border-color:var(--acc)}.metric .metric-label{display:block;font-size:12px;color:var(--mut)}.metric strong{display:block;font-size:29px;letter-spacing:-.04em;margin:9px 0}.metric small{color:var(--mut);font-size:11px}.metric .metric-arrow{position:absolute;right:14px;top:14px;color:var(--acc)}.metric-detail{margin-top:14px;padding:16px 18px;border:1px solid var(--line);border-radius:12px;line-height:1.6;font-size:13px}.insight-note{font-size:12px;color:var(--mut);line-height:1.6;margin:15px 0 0}.planning-summary{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap}.planning-summary strong{font-size:42px;letter-spacing:-.04em}.planning-summary span{color:var(--mut)}.planning-form{display:flex;gap:14px;flex-wrap:wrap;margin:18px 0}.planning-form label{font-size:12px;color:var(--mut);flex:1;min-width:140px}.planning-form input,.insight-tools select{display:block;margin-top:7px;border:1px solid var(--line);border-radius:9px;background:var(--card);color:var(--ink);padding:10px;font:inherit;width:100%}.planning-result{padding:14px 16px;border-radius:10px;background:var(--soft);font-weight:650;line-height:1.6}.insight-tools{display:flex;gap:10px;align-items:end;flex-wrap:wrap;margin-bottom:16px}.insight-tools label{font-size:12px;color:var(--mut)}.insight-tools select{width:auto;min-width:110px}.insight-tools button{margin:0 0 0 auto}.ride-chart{width:100%;height:auto;display:block;max-height:210px}.ride-chart text{font-family:inherit;fill:var(--mut);font-size:12px}.ride-chart rect{fill:var(--acc);opacity:.8}.ride-chart rect:hover{opacity:1}.ride-table{width:100%;border-collapse:collapse;font-size:13px}.ride-table th{text-align:left;color:var(--mut);font-size:11px;font-weight:600;padding:12px 8px}.ride-table td{padding:13px 8px;border-top:1px solid var(--line)}.ride-table th:last-child,.ride-table td:last-child{text-align:right}.ride-scroll{overflow-x:auto}.empty-insight{padding:28px 18px;background:var(--soft);border-radius:12px;color:var(--mut);font-size:13px;line-height:1.7}.connection-steps{display:grid;gap:0}.connection-step{display:flex;gap:12px;align-items:start;padding:15px 0;border-bottom:1px solid var(--line)}.connection-dot{width:10px;height:10px;border-radius:50%;background:var(--mut);margin:5px 0}.connection-dot.ok{background:#43a047}.connection-dot.warn{background:#ef9b35}.connection-step strong{font-size:14px}.connection-step p{font-size:12px;color:var(--mut);margin:5px 0;line-height:1.6}.cap-filter{margin:15px 0}.cap-filter input{padding:10px;border:1px solid var(--line);border-radius:9px;background:var(--card);color:var(--ink);width:100%;font:inherit}summary{cursor:pointer;line-height:1.6}.insight-panel details{margin-top:18px}.insight-shell button:focus-visible,.insight-shell input:focus-visible,.insight-shell select:focus-visible{outline:2px solid var(--acc);outline-offset:3px}@media(min-width:1050px){.metric-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}@media(max-width:520px){.insight-head,.insight-panel{padding:18px}.insight-head{flex-direction:column;gap:10px}.metric{padding:14px}.metric strong{font-size:24px}.insight-nav{padding:0 6px}.insight-nav button{padding:12px 10px;font-size:13px}.insight-tools button{margin:0}.planning-summary strong{font-size:34px}}
